import sys

class Q:

	def __init__(self, ll, i):
		self.ll = ll
		self.i = i

class Main:

	def __init__(self):
		self.buff = None
		self.index = 0

	def next(self):
		if self.buff is None or self.index == len(self.buff):
			self.buff = sys.stdin.readline().split()
			self.index = 0
		val = self.buff[self.index]
		self.index += 1
		return val

	def next_int(self):
		return int(self.next())

	def solve(self):
		n = self.next_int()
		ss = 0
		ans = 0
		for _ in range(0, n):
			d = self.next_int()
			re = ss - 3 * ans
			ss += d
			if d >= re * 2:
				ans += re + (d - re * 2) // 3
			else:
				ans += d // 2
		print(ans)
Main().solve()
